package com.tacz.guns.api.item;import net.minecraft.world.item.ItemStack;public class IGun {public static IGun getIGunOrNull(ItemStack stack){return new IGun();}public void setGunId(ItemStack stack,Object id){stack.gunId=id.toString();}public void setCurrentAmmoCount(ItemStack stack,int count){stack.rounds=count;}public void setBulletInBarrel(ItemStack stack,boolean value){stack.chambered=value;}public void setFireMode(ItemStack stack,Object mode){stack.mode=mode.toString();}}